import { useState } from 'react';

type Props = { min?: number; max?: number; initial?: number };

export default function {{component_name}}({ min = 0, max = 99, initial = 0 }: Props) {
  const [n, setN] = useState(initial);
  return (
    <div className="inline-flex items-center gap-2">
      <button onClick={() => setN((v) => Math.max(min, v - 1))}>-</button>
      <input
        type="number"
        value={n}
        onChange={(e) => setN(Math.max(min, Math.min(max, Number(e.target.value))))}
        className="w-16 text-center border rounded"
      />
      <button onClick={() => setN((v) => Math.min(max, v + 1))}>+</button>
    </div>
  );
}
